def build_tables(n, p):
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % p
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], p - 2, p)
    for k in range(n, 0, -1):
        inv_fact[k - 1] = inv_fact[k] * k % p
    return fact, inv_fact

