def count_queries(queries, p):
    if not queries:
        return []
    n = max(q[0] for q in queries)
    fact, inv_fact = build_tables(n, p)
    out = []
    for n, k in queries:
        if k < 0 or k > n:
            out.append(0)
        else:
            out.append(fact[n] * inv_fact[k] % p * inv_fact[n - k] % p)
    return out

